#nullable enable

using Campaigns.Contracts;
using Campaigns.Views;
using Marten;
// WaitForNonStaleProjectionDataAsync is an extension in Marten.Events.TestingExtensions, NOT an
// IDocumentStore member. Every doc page calls it bare with no using shown, so the compiler's
// "no accessible extension method" is the only hint and it does not say where to look.
using Marten.Events;
using Shouldly;
using Xunit;

namespace Campaigns.IntegrationTests.Slices.Campaigns;

/// <summary>
/// Generated from the model's GIVEN/THEN cells, NOT from the implementation. Pattern: view. Status: ready.
/// Owned by backend-agent. No WHEN: a read model only reads events that already exist.
///
/// THIS VIEW IS THE ONE THAT MUST WAIT. <c>CampaignDashboard</c> is a <c>MultiStreamProjection</c> registered
/// <c>Async</c> in ViewRegistrations — Marten's own default for multi-stream, because concurrent writes to
/// different streams landing on one row can stomp each other into apparent event skipping. The price is paid
/// here: every assertion below is preceded by <c>WaitForNonStaleProjectionDataAsync</c>, where the four
/// Inline views in this project assert directly. That is the whole Inline/Async trade, visible as a line of
/// test code.
///
/// A wait is not a sleep and not a retry loop: it blocks until the async daemon has caught up to at least
/// the last event captured when it was called. Getting it wrong does not fail — it produces a test that
/// passes on a fast machine and flakes on a slow one, which is worse than a red suite.
///
/// MEASURED RATHER THAN ASSUMED: with the wait deleted from <c>Row</c> and nothing else changed, all three
/// tests below fail immediately — "row" null in the first, <c>row.Queued</c> in the second,
/// <c>before.Queued</c> in the third. So the wait is not a precaution here, it is the only reason an Async
/// view is readable at all; and on a busier machine the same code without it would have failed
/// intermittently instead, which is the shape that gets a test deleted rather than fixed.
///
/// STREAM KEYS ARE FIXED VALUES, and for this view that is load-bearing in a way it is not for the others.
/// <c>MessageToCampaignGrouper</c> keeps a <c>ConcurrentDictionary</c> of messageId → campaignId for the
/// lifetime of the store, and <c>ResetAllMartenDataAsync</c> cannot clear it: it wipes the database, not the
/// projection's own memory. So a messageId reused under a DIFFERENT campaign in a later test is resolved
/// from the stale entry — the DB lookup is skipped precisely because the key is already known — and the
/// outcome lands on a campaign whose row no longer exists.
///
/// MEASURED, with two tests appending the same messageId under two campaigns and a wait between the queue
/// event and the outcome so the grouper's batch scan cannot correct it: the SECOND to run fails with
/// <c>row.Delivered should be 1 but was 0</c>. Nothing is thrown and nothing is logged — the same silent
/// shape the batch scan exists to prevent, arriving by a different route.
///
/// Every test in this suite therefore pairs SeedData.MessageId with SeedData.CampaignId, so the cache can
/// only ever hold the answer it would compute anyway. In production a message is never re-pointed at another
/// campaign, so this is a test-isolation hazard rather than a bug — but it is one an implementing agent will
/// meet the first time it writes a second test against a grouped view.
/// </summary>
public sealed class CampaignDashboardTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static readonly TimeSpan DaemonTimeout = TimeSpan.FromSeconds(20);

    /// <summary>
    /// Wait, then read. Written once because the wait is not optional for this view and a test that forgets
    /// it looks exactly like a test that passes.
    /// </summary>
    private async Task<CampaignDashboard?> Row(Guid campaignId)
    {
        await Store.WaitForNonStaleProjectionDataAsync(DaemonTimeout);
        await using var session = Store.QuerySession();
        return await session.LoadAsync<CampaignDashboard>(campaignId);
    }

    // an opened campaign appears with nothing sent
    //   GIVEN CampaignOpened
    //   THEN  CampaignDashboard
    [Fact]
    public async Task AnOpenedCampaignAppearsWithNothingSent()
    {
        var campaignId = SeedData.CampaignId;
        await Given(campaignId, new CampaignOpened(campaignId, "January newsletter", SeedData.SeededAt));

        var row = await Row(campaignId);

        row.ShouldNotBeNull();
        row.Id.ShouldBe(campaignId);
        row.CampaignId.ShouldBe(campaignId);
        row.Name.ShouldBe("January newsletter");

        // derived="status=CampaignOpened+CampaignClosed" — a fold over event PRESENCE. No event carries a
        // status, and the absence of a closure is what "Open" means.
        row.Status.ShouldBe(CampaignDashboard.Open);

        // The row exists from ONE stream, before the other stream type has produced anything at all. A
        // multi-stream projection that only wrote a row once it had seen a Message event would leave a
        // freshly opened campaign missing from the dashboard, and the next GT would still pass.
        row.Queued.ShouldBe(0);
        row.Delivered.ShouldBe(0);
        row.Bounced.ShouldBe(0);
    }

    // messages from another stream roll up onto the campaign
    //   GIVEN CampaignOpened, MessageQueued, MessageDelivered
    //   THEN  CampaignDashboard
    [Fact]
    public async Task MessagesFromAnotherStreamRollUpOntoTheCampaign()
    {
        var campaignId = SeedData.CampaignId;
        var messageId = SeedData.MessageId;

        // THREE EVENTS, TWO STREAMS, THREE TRANSACTIONS. The Campaign stream and the Message stream are
        // different streams of different TYPES — which is the entire reason this view cannot be a
        // single-stream projection, and the one claim in this model that only this GT makes.
        await Given(campaignId, new CampaignOpened(campaignId, "January newsletter", SeedData.SeededAt));
        await Given(messageId, new MessageQueued(
            messageId, campaignId, QueueMessageTests.SenderId, "January newsletter",
            ["a@example.com", "b@example.com"], SeedData.SeededAt));
        await Given(messageId, new MessageDelivered(messageId, "a@example.com", SeedData.SeededAt));

        var row = await Row(campaignId);

        row.ShouldNotBeNull();

        // From the Campaign stream. The Message stream carries no campaign name.
        row.Name.ShouldBe("January newsletter");
        row.Status.ShouldBe(CampaignDashboard.Open);

        // From the Message stream. The Campaign stream carries no counters.
        row.Queued.ShouldBe(1);

        // And this one is the sharp case: MessageDelivered carries messageId and recipient and NO
        // campaignId, so nothing in its payload says which row it belongs on. It lands here because the
        // projection's grouper resolves the message to its campaign through an inline lookup. The same-batch
        // variant — the queue event and the outcome inside ONE daemon page — is measured separately in
        // ProjectionRecipeTests, because only appending both in one transaction can force it.
        row.Delivered.ShouldBe(1);
        row.Bounced.ShouldBe(0);
    }

    // closing a campaign changes its status and nothing else
    //   GIVEN CampaignOpened, MessageQueued, CampaignClosed
    //   THEN  CampaignDashboard
    [Fact]
    public async Task ClosingACampaignChangesItsStatusAndNothingElse()
    {
        var campaignId = SeedData.CampaignId;
        var messageId = SeedData.MessageId;

        await Given(campaignId, new CampaignOpened(campaignId, "January newsletter", SeedData.SeededAt));
        await Given(messageId, new MessageQueued(
            messageId, campaignId, QueueMessageTests.SenderId, "January newsletter",
            ["a@example.com", "b@example.com"], SeedData.SeededAt));

        // The BEFORE. "Nothing else changed" is a claim about a difference, so it needs one — asserting the
        // counts against the literal 1 would not distinguish "survived the closure" from "recomputed to the
        // same number by luck".
        var before = await Row(campaignId);
        before.ShouldNotBeNull();
        before.Queued.ShouldBe(1);
        before.Status.ShouldBe(CampaignDashboard.Open);

        await Given(campaignId, new CampaignClosed(campaignId, SeedData.SeededAt));

        var after = await Row(campaignId);
        after.ShouldNotBeNull();

        // A REVISE, NOT A REBUILD. An Apply that returned a fresh view instead of `view with { … }` would
        // zero the counts accumulated from the OTHER stream, and every number on the dashboard of every
        // closed campaign would silently be nought. No compiler and no other test would say a word.
        //
        // Asserted as one comparison rather than field by field, because a field-by-field version stops
        // covering any field added later. The status change is IN the expected value, which is also what
        // makes this non-vacuous on an Async view: if the daemon had not yet processed CampaignClosed the
        // row would still read Open and this would fail rather than quietly agree.
        after.ShouldBe(before with { Status = CampaignDashboard.Closed });
    }
}
